item.content:encoded:
#nav-menu-item-7878 .second {display: none;}
.logged-in #nav-menu-item-7878 .second {display: block;}

.search_single .query_box_direct_value, .instance_search_input {
	min-height:30px;
	width:98%;
}
.side_menu_button {
	line-height:18px;
}
.woocommerce-error {
	background:#ffc9c9 !important;
}
.woocommerce .quantity input.qty {
	width:50px;
}
.woocommerce-cart .woocommerce .woocommerce-message, .sku_wrapper, .tagged_as {
    display:none !important;
}
.wpt_product_table_wrapper div.tables_cart_message_box div.widget_shopping_cart_content .total {
	font-size:20px;
	font-weight:bold;
	background:#f7f7f7;
	padding:10px;
	margin:15px 0 15px 0;
}
.wpt_product_table_wrapper div.tables_cart_message_box div.widget_shopping_cart_content .buttons {
	float:none;
	margin-bottom:20px;
}
.screen-reader-text {
	display:none !important;
}
h3.search_box_label {
	font-size:24px;
	color:#77993A;	
}
.custom_table tbody tr a.button {
	padding:0 25px;
}
.pvtfw_variant_table_block .variant {
	margin:15px 0 30px 0;
	width:100%;
}
.shopping_cart_dropdown ul li, .shopping_cart_dropdown .shopping_cart_dropdown_inner {
	display:none;
}
.woocommerce div.cart-collaterals div.cart_totals {
	width:33%
}
.woocommerce div.cart-collaterals div.cart_totals th {
	padding-left:15px;
	width:50%;
}
.woocommerce .product .onsale.out-of-stock-button {
	line-height:4;
	font-size:10px;
}
.woocommerce-product-details__short-description, .woocommerce-shipping-destination {
	display:none;
}

